// Split "headers + body" (retrieve mode BOTH) into status code and body.
// A value that does not start with HTTP/ is the transport-error marker (no HTTP response).
// Loops so proxy CONNECT header blocks or 1xx blocks are skipped.
function split(v) {
  var code = 0, body = String(v);
  while (body.indexOf('HTTP/') === 0) {
    var m = /^HTTP\/[0-9.]+\s+([0-9]{3})/.exec(body);
    code = m ? parseInt(m[1], 10) : 0;
    var i = body.search(/\r?\n\r?\n/);
    if (i < 0) { body = ''; break; }
    body = body.substring(i).replace(/^\r?\n\r?\n/, '');
  }
  return {code: code, body: body};
}
function hint(code) {
  if (code === 0) return 'No HTTP response (DNS, TLS, timeout or connection refused)';
  if (code === 401) return 'HTTP 401: authentication failed, check token ID and secret';
  if (code === 403) return 'HTTP 403: access denied, check Auditor ACL on /resource for both user and token';
  if (code === 404) return 'HTTP 404: endpoint not found, check URL and PDM version';
  return 'HTTP ' + code + ': unexpected response';
}
function num(x) { return typeof x === 'number' && isFinite(x) && x >= 0; }
function put(o, k, v) { if (num(v)) o[k] = v; }
function pct(o, k, used, total) { if (num(used) && num(total) && total > 0) o[k] = 100 * used / total; }
function str(x) { return typeof x === 'string' && x !== ''; }
// Host metrics shared by PVE nodes, guests and PBS nodes. cpu is a 0..1 fraction of maxcpu.
function load(e, x) {
  if (num(x.cpu)) e.cpu = 100 * x.cpu;
  put(e, 'cpus', x.maxcpu);
  put(e, 'mem', x.mem);
  put(e, 'maxmem', x.maxmem);
  pct(e, 'mempused', x.mem, x.maxmem);
  put(e, 'uptime', x.uptime);
}

// Output: {"http":200,"summary":{..},"remote":{<remote>:{..}},"node":{<remote>/<node>:{..}},
//   "guest":{<remote>/<vmid>:{..}},"storage":{<key>:{..}},"pbsnode":{<remote>/<name>:{..}},
//   "datastore":{<remote>/<name>:{..}},"lld":{<kind>:[{"{#MACRO}":..}]}}
// or {"http":<code>,"error":"<reason>"} when the request failed. Fields that are missing or invalid
// are left out, so the dependent items discard them instead of storing zero.
try {
  var r = split(value);
  if (r.code !== 200) return JSON.stringify({http: r.code, error: hint(r.code)});
  var b;
  try { b = JSON.parse(r.body); } catch (e) { b = null; }
  if (!b || !Array.isArray(b.data)) {
    return JSON.stringify({http: 200, error: 'HTTP 200 but response has no data array, check URL'});
  }
  var s = {remotes: 0, remotes_failed: 0, pve_nodes_online: 0, pve_nodes_down: 0,
    qemu_running: 0, qemu_stopped: 0, lxc_running: 0, lxc_stopped: 0,
    storage_available: 0, storage_unavailable: 0, pbs_datastores: 0, pbs_datastores_maintenance: 0,
    pve_mem_used: 0, pve_mem_total: 0, pve_storage_used: 0, pve_storage_total: 0,
    pbs_storage_used: 0, pbs_storage_total: 0};
  var o = {http: 200, summary: s, remote: {}, node: {}, guest: {}, storage: {}, pbsnode: {}, datastore: {}};
  var lld = {remote: [], node: [], guest: [], storage: [], pbsnode: [], datastore: []};
  var cpuUsed = 0, cpuTotal = 0;
  for (var i = 0; i < b.data.length; i++) {
    var rr = b.data[i];
    if (!rr || !str(rr.remote) || o.remote[rr.remote]) continue;
    var rn = rr.remote, err = str(rr.error) ? rr.error : null;
    s.remotes++;
    if (err) s.remotes_failed++;
    o.remote[rn] = {reachable: err ? 0 : 1, error: err || 'OK'};
    lld.remote.push({'{#REMOTE}': rn, '{#KEY}': rn});
    var res = Array.isArray(rr.resources) ? rr.resources : [];
    for (var j = 0; j < res.length; j++) {
      var x = res[j], k, e;
      if (!x || typeof x.type !== 'string') continue;
      if (x.type === 'pve-node' && str(x.node)) {
        k = rn + '/' + x.node;
        if (o.node[k]) continue;
        e = {status: x.status === 'online' ? 1 : x.status === 'offline' ? 0 : 2};
        // An offline node reports zeros, so metrics are only kept while online.
        if (e.status === 1) {
          s.pve_nodes_online++;
          load(e, x);
          if (num(x.cpu) && num(x.maxcpu)) { cpuUsed += x.cpu * x.maxcpu; cpuTotal += x.maxcpu; }
          if (num(x.mem) && num(x.maxmem)) { s.pve_mem_used += x.mem; s.pve_mem_total += x.maxmem; }
        } else {
          s.pve_nodes_down++;
        }
        o.node[k] = e;
        lld.node.push({'{#REMOTE}': rn, '{#NODE}': x.node, '{#KEY}': k});
      } else if ((x.type === 'pve-qemu' || x.type === 'pve-lxc') && num(x.vmid) && x.template !== true) {
        var gt = x.type.substring(4);
        k = rn + '/' + x.vmid;
        if (o.guest[k]) continue;
        e = {status: x.status === 'running' ? 1 : x.status === 'stopped' ? 0 : 2, node: str(x.node) ? x.node : 'unknown'};
        if (e.status === 1) {
          s[gt + '_running']++;
          load(e, x);
          // QEMU guests report disk 0 without a guest agent, so disk usage is only kept for LXC.
          if (gt === 'lxc') {
            put(e, 'disk', x.disk);
            put(e, 'maxdisk', x.maxdisk);
            pct(e, 'diskpused', x.disk, x.maxdisk);
          }
        } else if (e.status === 0) {
          s[gt + '_stopped']++;
        }
        o.guest[k] = e;
        lld.guest.push({'{#REMOTE}': rn, '{#VMID}': String(x.vmid), '{#NAME}': str(x.name) ? x.name : String(x.vmid),
          '{#TYPE}': gt, '{#KEY}': k});
      } else if (x.type === 'pve-storage' && str(x.storage) && str(x.node)) {
        // Shared storage is listed once per node; keep one entry per remote, preferring an available one.
        var shared = x.shared === true;
        k = shared ? rn + '/' + x.storage : rn + '/' + x.node + '/' + x.storage;
        var prev = o.storage[k], st = x.status === 'available' ? 1 : 2;
        if (prev && (prev.status === 1 || st !== 1)) continue;
        e = {status: st};
        if (st === 1) {
          put(e, 'used', x.disk);
          put(e, 'total', x.maxdisk);
          pct(e, 'pused', x.disk, x.maxdisk);
        }
        if (!prev) lld.storage.push({'{#REMOTE}': rn, '{#STORAGE}': x.storage, '{#NODE}': shared ? 'shared' : x.node, '{#KEY}': k});
        o.storage[k] = e;
      } else if (x.type === 'pbs-node') {
        var nn = str(x.name) ? x.name : 'localhost';
        k = rn + '/' + nn;
        if (o.pbsnode[k]) continue;
        e = {};
        load(e, x);
        o.pbsnode[k] = e;
        lld.pbsnode.push({'{#REMOTE}': rn, '{#NODE}': nn, '{#KEY}': k});
      } else if (x.type === 'pbs-datastore' && str(x.name)) {
        k = rn + '/' + x.name;
        if (o.datastore[k]) continue;
        e = {maintenance: str(x.maintenance) ? 1 : 0};
        put(e, 'used', x.disk);
        put(e, 'total', x.maxdisk);
        pct(e, 'pused', x.disk, x.maxdisk);
        s.pbs_datastores++;
        if (e.maintenance) s.pbs_datastores_maintenance++;
        if (num(x.disk) && num(x.maxdisk)) { s.pbs_storage_used += x.disk; s.pbs_storage_total += x.maxdisk; }
        o.datastore[k] = e;
        lld.datastore.push({'{#REMOTE}': rn, '{#DATASTORE}': x.name, '{#KEY}': k});
      }
    }
  }
  for (var sk in o.storage) {
    var se = o.storage[sk];
    if (se.status === 1) {
      s.storage_available++;
      if (num(se.used) && num(se.total)) { s.pve_storage_used += se.used; s.pve_storage_total += se.total; }
    } else {
      s.storage_unavailable++;
    }
  }
  if (cpuTotal > 0) s.pve_cpu_util = 100 * cpuUsed / cpuTotal;
  pct(s, 'pve_mem_pused', s.pve_mem_used, s.pve_mem_total);
  pct(s, 'pve_storage_pused', s.pve_storage_used, s.pve_storage_total);
  pct(s, 'pbs_storage_pused', s.pbs_storage_used, s.pbs_storage_total);
  o.lld = lld;
  return JSON.stringify(o);
} catch (e) {
  return JSON.stringify({http: 0, error: 'Preprocessing failure: ' + e});
}
